// Fichier genere : traductions de l'interface. Cle = texte francais du code. Pour corriger ou ajouter une langue sans toucher au code :
// %APPDATA%\AR6DoF\lang\xx.txt (voir le LISEZMOI).
namespace AR6DoF
{
    /// <summary>Traductions fournies (en, es, de, it, pt). Format : texte francais => traduction, une ligne par texte.</summary>
    public static class Ar6dofLangData
    {
        public static string Get(string code)
        {
            switch (code)
            {
                case "en": return En;
                case "es": return Es;
                case "de": return De;
                case "it": return It;
                case "pt": return Pt;
                default: return "";
            }
        }

