            "Format 24 h (decoche : 12 h avec AM / PM) => 24-hour format (off: 12-hour with AM / PM)",
            "Afficher la date => Show the date",
            "Afficher la batterie du PC => Show the PC battery",
            "Affichage de la batterie => Battery display",
            "Icone => Icon",
            "Icone, pourcentage, temps restant => Icon, percentage, time left",
            "Un PC fixe n'a pas de batterie : le dock affiche alors une prise (Secteur). Rien de tout cela ne tourne quand les trois cases sont decochees. => A desktop PC has no battery: the dock then shows a plug (Mains power). None of this runs when all three boxes are unchecked.",
            "Heure avec plein de cadrans, chronometre, minuteur et alarmes. => Time with lots of faces, stopwatch, timer and alarms.",
            "Heure avec plein de cadrans, chronometre, minuteur et alarmes (a renommer, AM / PM). Les alarmes sonnent meme application fermee. => Time with lots of faces, stopwatch, timer and alarms (renamable, AM / PM). Alarms ring even when the app is closed.",
            "Principal => Main",
            "Touche une valeur (balance, graves, medium, aigus) pour la remettre a zero. Limiteur : plafond 0 dB, doux des -3 dB. Le vumetre Principal est avant le limiteur : voyant rouge = ca sature. => Tap a value (balance, bass, mid, treble) to reset it to zero. Limiter: 0 dB ceiling, soft from -3 dB. The Main meter sits before the limiter: red light = it is clipping.",
            "   paupieres : gauche {0} %, droite {1} % =>    eyelids: left {0} %, right {1} %",
            "Test => Test",
            "Ressenti => Feels like",
            "Avancer dans le temps => Move forward in time",
            "Effets de vent => Wind effects",
            "Vent dans le coin => Wind in the corner",
            "Choisis ce que montre l'ecran Maintenant. Ce qui est cache ne coute rien. => Choose what the Now screen shows. Anything hidden costs nothing.",
            "Cases d'information => Info tiles",
            "Ecran Maintenant => Now screen",
            "Voir et tester tous les temps (onglet Test) => See and test every kind of weather (Test tab)",
            "Source : Windows (Wi-Fi / GPS) => Source: Windows (Wi-Fi / GPS)",
            "Source : adresse IP (approximatif) => Source: IP address (approximate)",
            "Source : coordonnees saisies => Source: typed coordinates",
            "Source : ville choisie => Source: chosen city",
            "Source : inconnue => Source: unknown",
            "Pas encore de meteo. Verifie ta connexion internet ou choisis ta ville dans l'onglet Lieu. Les effets 3D se voient quand meme dans l'onglet Test. => No weather yet. Check your internet connection or pick your city in the Place tab. You can still see the 3D effects in the Test tab.",
            "Un PC fixe n'a pas de GPS : Windows et internet ne donnent que la zone de ton fournisseur d'acces, parfois a des dizaines de km (la source est affichee en haut). Pour une position exacte, entre tes coordonnees ci-dessous ou cherche ta ville. => A desktop PC has no GPS: Windows and the internet only give the area of your internet provider, sometimes tens of km away (the source is shown at the top). For an exact position, type your coordinates below or search for your city.",
            "Coordonnees exactes (latitude, longitude) => Exact coordinates (latitude, longitude)",
            "Utiliser => Use",
            "Coordonnees non valides. Exemple : 47.39, 0.68 => Invalid coordinates. Example: 47.39, 0.68",
            "Astuce : sur une carte en ligne, clic droit sur ton adresse, puis copie les deux nombres (latitude puis longitude). => Tip: on an online map, right-click your address, then copy the two numbers (latitude, then longitude).",
            "Dans => In",
            "Lecture => Play",
            "Pluie a cette heure => Rain at this hour",
            "Vent {0} {1} => Wind {0} {1}",
            "Type de temps => Weather type",
            "Conditions => Conditions",
            "Heure du jour => Time of day",
            "Temperature => Temperature",
            "Calme => Calm",
            "Brise => Breeze",
            "Vent fort => Strong wind",
            "Tempete => Storm",
            "Tour automatique des temps => Automatic weather tour",
            "Le tour automatique passe tous les temps en revue, du ciel degage a l'orage et a la grele. Les curseurs changent l'heure (le soleil et la lune se deplacent), le vent (arbres, moulin, traits de vent) et la temperature (gel, canicule). => The automatic tour goes through every kind of weather, from clear sky to thunderstorm and hail. The sliders change the time (sun and moon move), the wind (trees, windmill, wind streaks) and the temperature (frost, heat wave).",
            "Assis : dock sous les yeux de (cm) => Seated: dock below the eyes by (cm)",
            "Vue : Normale => View: Normal",
            "Vue => View",
            "Camera => Camera",
            "Cameras => Cameras",
            "Vision nocturne => Night vision",
            "Thermique => Thermal",
            "Autre (retroviseur, miroir...) => Other (rear view, mirror...)",
            "Chaud = blanc => Hot = white",
            "Chaud = noir => Hot = black",
            "Fer (noir, rouge, jaune) => Iron (black, red, yellow)",
            "Blanc => White",
            "Couleurs d'origine => Original colors",
            "Une seule image (faux stereo) => One image (fake stereo)",
            "Deux images cote a cote => Two images side by side",
            "Deux images haut / bas => Two images top / bottom",
            "Arretee (elle ne tourne que quand on s'en sert) => Stopped (it only runs while in use)",
            "Erreur :  => Error: ",
            "En marche : {0} x {1}, {2} img/s => Running: {0} x {1}, {2} fps",
            "LED infrarouge : non utilisee => Infrared LED: not used",
            "LED : choisis un menu d'appareil Bluetooth => LED: choose a Bluetooth device menu",
            "LED : choisis le controle de ce menu => LED: choose this menu's control",
            "LED : appareil Bluetooth pas connecte => LED: Bluetooth device not connected",
            "LED : allumee => LED: on",
            "LED : eteinte => LED: off",
            "Cameras supplementaires => Extra cameras",
            "La camera normale (celle du tracking) ne change jamais. Ajoute ici une camera de vision nocturne, thermique ou autre (derriere ta tete...). Rien ne tourne tant qu'une camera n'est pas utilisee ; le bouton Vue du dock n'apparait que s'il y en a une activee. => The normal camera (the tracking one) never changes. Add a night vision, thermal or other camera here (behind your head...). Nothing runs until a camera is used; the dock's View button only appears when one is enabled.",
            "Cameras indisponibles => Cameras unavailable",
            "Aucune camera : ajoutes-en une => No camera: add one",
            "Ajouter une camera => Add a camera",
            "Supprimer cette camera => Delete this camera",
            "Confirmer : supprimer => Confirm: delete",
            "Cette camera => This camera",
            "Activee (bouton Vue du dock, application Miroir) => Enabled (dock View button, Mirror app)",
            "Voir cette camera dans le casque maintenant => See this camera in the headset now",
            "Source de l'image => Image source",
            "Camera USB => USB camera",
            "Flux reseau (http) => Network stream (http)",
            "premiere camera => first camera",
            "Actualiser la liste des cameras USB => Refresh the USB camera list",
            "Images par seconde => Frames per second",
            "Ne choisis pas la camera du tracking : elle est deja utilisee par ar6dof_probe. => Do not pick the tracking camera: ar6dof_probe already uses it.",
            "Adresse du flux d'images (MJPEG) => Image stream address (MJPEG)",
            "Une camera Wi-Fi (ESP32-CAM, camera IP...) qui envoie du MJPEG. Un identifiant se met dans l'adresse : http://nom:mot@adresse/flux. Le RTSP n'est pas gere. => A Wi-Fi camera (ESP32-CAM, IP camera...) that sends MJPEG. A login goes in the address: http://name:pass@address/stream. RTSP is not supported.",
            "Contenu de l'image => Image content",
            "Echanger gauche / droite (si deux images) => Swap left / right (if two images)",
            "Image et IPD => Image and IPD",
            "Une seule image sert aux deux yeux (faux stereo : pas de relief). L'IPD ecarte ou rapproche l'image dans chaque oeil, comme l'IPD logiciel de l'image normale (les deux s'ajoutent). => A single image serves both eyes (fake stereo: no depth). The IPD moves the image apart or closer in each eye, like the software IPD of the normal image (the two add up).",
            "Champ de la camera (deg) => Camera field of view (deg)",
            "IPD de cette camera (+ = ecarte) => IPD of this camera (+ = apart)",
            "Delai de l'image (ms) => Image delay (ms)",
            "Rotation => Rotation",
            "Type de camera => Camera type",
            "Gain (%) => Gain (%)",
            "Luminosite (%) => Brightness (%)",
            "Palette => Palette",
            "Contraste (%) => Contrast (%)",
            "Niveau (%) => Level (%)",
            "Image affichee telle quelle : pour une camera libre (derriere la tete...), ouvre l'application Miroir. Une camera 'Autre' n'apparait pas dans le bouton Vue du dock. => Image shown as is: for a free camera (behind the head...), open the Mirror app. An 'Other' camera does not appear in the dock's View button.",
            "Le suivi de position reste toujours sur la camera normale. L'effet (vert, palette) est applique par la carte graphique, sans cout quand la camera est arretee. => Position tracking always stays on the normal camera. The effect (green, palette) is applied by the graphics card, at no cost when the camera is stopped.",
            "LED infrarouge => Infrared LED",
            "Pour une camera de vision nocturne sans eclairage propre. Cree d'abord dans Apps > Nouvel appareil un menu Bluetooth pour ta LED, avec un curseur (puissance) ou un interrupteur, puis choisis-le ici. La LED s'allume seulement quand la camera tourne. => For a night vision camera without its own lighting. First create a Bluetooth menu for your LED in Apps > New device, with a slider (power) or a switch, then pick it here. The LED only turns on while the camera runs.",
            "Allumer une LED infrarouge avec cette camera => Turn on an infrared LED with this camera",
            "Menu Bluetooth => Bluetooth menu",
            "Controle => Control",
            "Puissance (%) => Power (%)",
            "Tester la LED => Test the LED",
            "Eteindre la LED (test) => Turn the LED off (test)",
            "Une camera libre (derriere ta tete...) dans une fenetre => A free camera (behind your head...) in a window",
            "Une camera libre (derriere ta tete, sur la queue...) dans une fenetre : effet miroir, retournement, taille. Elle ne tourne que fenetre affichee. => A free camera (behind your head, on your tail...) in a window: mirror effect, flip, size. It only runs while the window is shown.",
            "Aucune camera n'est activee. Ajoute-en une dans Reglages > Image > Cameras (camera USB ou flux reseau), par exemple celle placee derriere ta tete. => No camera is enabled. Add one in Settings > Image > Cameras (USB camera or network stream), for example the one behind your head.",
            "Effet miroir : oui => Mirror effect: yes",
            "Effet miroir : non => Mirror effect: no",
            "Retourne : oui => Flipped: yes",
            "Retourne : non => Flipped: no",
            "Petit => Small",
            "Moyen => Medium",
            "Grand => Large",
            "Pour regler la camera (source, image, vision nocturne, LED...) : Reglages > Image > Cameras. La camera s'arrete quand cette fenetre est rangee. => To set up the camera (source, image, night vision, LED...): Settings > Image > Cameras. The camera stops when this window is put away.",
            "Plus => More",
            "Ville estimee par internet (peut etre fausse) => City estimated from the internet (may be wrong)",
            "Source : position saisie => Source: entered position",
            "Ce n'est pas ma ville ? Choisir ma ville => Not my city? Choose my city",
            "Ma ville => My city",
            "Cherche ta ville, choisis-la dans la liste : elle est gardee, et plus jamais remplacee par une estimation. Aucune coordonnee n'est affichee. => Search your city and pick it in the list: it is kept and never replaced by an estimate. No coordinates are shown.",
            "Position automatique => Automatic position",
            "Utiliser la position de Windows (Wi-Fi / GPS) => Use Windows location (Wi-Fi / GPS)",
            "Estimer par internet => Estimate from the internet",
            "Un PC fixe n'a pas de GPS : Windows et internet ne donnent que la zone de ton fournisseur d'acces, parfois a des dizaines de km. La position est arrondie a 1 km environ et jamais affichee. => A desktop PC has no GPS: Windows and the internet only give your provider's area, sometimes tens of km away. The position is rounded to about 1 km and never shown.",
            "Coordonnees (avance) => Coordinates (advanced)",
            "latitude, longitude => latitude, longitude",
            "Ma position => My position",
            "Scene 3D => 3D scene",
            "Hauteur de l'ile => Island height",
            "Taille du cadre => Frame size",
            "Comme avant => As before",
            "Un peu plus bas => A bit lower",
            "Plus bas => Lower",
            "Tres bas => Very low",
            "Page Plus => More page",
            "Page Plus (tester tous les temps) => More page (test all weather)",
            "La page Plus permet de voir tous les types de temps a la main (heure, vent, temperature). Elle reste cachee tant que tu ne l'actives pas. => The More page lets you see every kind of weather by hand (time, wind, temperature). It stays hidden until you enable it.",
            "Ouvrir la page Plus => Open the More page",
            "Alchimie => Alchemy",
            "Ambiance => Ambience",
            "Cubes => Cubes",
            "Particules => Particles",
            "Tunnel => Tunnel",
