            "Couleurs musicales => Musical colors",
            "Toile => Web",
            "Clic : agrandir / reduire => Click: enlarge / shrink",
            "DJ => DJ",
            "Boucle => Loop",
            "Charger... => Load...",
            "Ejecter => Eject",
            "Filtre => Filter",
            "Crossfader => Crossfader",
            "Mix => Mix",
            "Coupe => Cut",
            "Chargement... => Loading...",
            "Aucune piste : Charger... => No track: Load...",
            "BPM inconnu => BPM unknown",
            "Charger dans la platine A => Load into deck A",
            "Charger dans la platine B => Load into deck B",
            "La liste est vide. Ajoute des musiques (elles sont aussi dans l'onglet Musique). => The list is empty. Add music (it is shared with the Music tab).",
            "Retour aux platines => Back to the decks",
            "Une piste est lue en entier (10 minutes au maximum). L'analyse du tempo prend quelques secondes. => A track is read in full (10 minutes at most). Tempo analysis takes a few seconds.",
            "Les pistes sortent par la tranche Musique (son general inclus). Le tempo change aussi la hauteur du son (comme un tourne-disque). Les reperes ne sont pas gardes. => Tracks go out through the Music channel (main included). Tempo also changes the pitch (like a turntable). Cue points are not saved.",
            "Tempo 0 => Tempo 0",
            "Piste precedente => Previous track",
            "Piste suivante => Next track",
            "Lire / Pause => Play / Pause",
            "Notifications => Notifications",
            "Alarmes, evenements, problemes et musique en cours => Alarms, events, problems and music playing",
            "Musique en cours => Now playing",
            "Rien a signaler. => Nothing to report.",
            "Effacer => Clear",
            "Tout effacer => Clear all",
            "Connexion perdue => Connection lost",
            "Plus de donnees du casque (ar6dof_probe lance ?) => No more data from the headset (is ar6dof_probe running?)",
            "Suivi perdu => Tracking lost",
            "Le suivi de la tete ne fonctionne plus => Head tracking no longer works",
            "Calendrier => Calendar",
            "Evenement => Event",
            "Dans {0} min => In {0} min",
            "Evenements avec rappel avant leur debut, et scan d'une affiche ou d'un programme de convention. => Events with a reminder before they start, and scan of a poster or convention schedule.",
            "Evenements avec rappel avant leur debut. Scanne une affiche ou le programme d'une convention devant toi pour les creer. Le scan ne tourne que quand tu le lances. => Events with a reminder before they start. Scan a poster or a convention schedule in front of you to create them. The scan only runs when you start it.",
            "Calendrier indisponible. => Calendar unavailable.",
            "Agenda => Agenda",
            "Scanner => Scan",
            "(sans rappel) => (no reminder)",
            "Ajouter un evenement => Add an event",
            "Aucun evenement. Va dans Scanner pour lire une affiche ou un programme, ou ajoute-en un a la main. => No events. Go to Scan to read a poster or schedule, or add one by hand.",
            "Nouvel evenement => New event",
            "Modifier l'evenement => Edit event",
            "Nom de l'evenement => Event name",
            "Lieu (facultatif) => Place (optional)",
            "Duree inconnue => Unknown duration",
            "Duree => Duration",
            "Rappel avant le debut => Reminder before start",
            "Le rappel sonne {0} min avant (a regler dans Options). => The reminder rings {0} min before (set in Options).",
            "Tiens l'affiche ou le programme bien en face de toi, texte lisible et bien eclaire, sans bouger. Touche Lancer : photo dans 3 secondes, lecture du texte par Windows, puis tu relis les evenements avant de les enregistrer. Rien ne tourne avant ton clic. => Hold the poster or schedule right in front of you, text readable and well lit, without moving. Touch Start: photo in 3 seconds, text read by Windows, then you review the events before saving them. Nothing runs before your click.",
            "Lancer le scan => Start scan",
            "Scan dans {0} s... => Scan in {0} s...",
            "Photo... => Photo...",
            "Lecture du texte... => Reading text...",
            "Camera indisponible : le passthrough n'est pas pret => Camera unavailable: passthrough is not ready",
            "Photo impossible : {0} => Photo failed: {0}",
            "Photo impossible : rien n'a ete enregistre => Photo failed: nothing was saved",
            "Aucun horaire reconnu. Rapproche-toi, ameliore la lumiere, ou regarde le texte lu ci-dessous. => No time recognised. Get closer, improve the light, or look at the text read below.",
            "{0} evenement(s) trouve(s). Decoche ceux que tu ne veux pas, touche une ligne pour corriger. => {0} event(s) found. Untick the ones you don't want, touch a line to correct it.",
            "Enregistrer ({0}) => Save ({0})",
            "Nouveau scan => New scan",
            "Cacher le texte lu => Hide the text read",
            "Voir le texte lu => Show the text read",
            "Aucun texte lu. => No text read.",
            "Rien de nouveau a enregistrer => Nothing new to save",
            "{0} evenement(s) ajoute(s) => {0} event(s) added",
            "Rappel => Reminder",
            "Le rappel sonne avant le debut de l'evenement : => The reminder rings before the event starts:",
            "Le rappel passe par la sonnerie de l'horloge et laisse une ligne dans les notifications. Il sonne meme si cette fenetre est fermee. => The reminder uses the clock's ringtone and leaves a line in the notifications. It rings even if this window is closed.",
            "Scan => Scan",
            "La photo du scan est lue par Windows sur ton PC (rien n'est envoye sur Internet), puis supprimee tout de suite. => The scan photo is read by Windows on your PC (nothing is sent over the Internet), then deleted right away.",
            "Donnees => Data",
            "Confirmer : tout effacer ? => Confirm: clear everything?",
            "Effacer tous les evenements => Delete all events",
            "Delai depasse (la lecture du texte a pris plus de 45 s) => Timed out (reading the text took more than 45 s)",
            "Aucune langue avec reconnaissance de texte dans Windows (Parametres > Heure et langue > Langue : ajoute le francais) => No language with text recognition in Windows (Settings > Time & language > Language: add French)",
            "Qualite : normale => Quality: normal",
            "Qualite : 8 images accumulees => Quality: 8 frames stacked",
            "Qualite : 8 images, grille x2 => Quality: 8 frames, x2 grid",
            "Accumulation : reste immobile une seconde ; le calcul prend 1 a 3 s. => Stacking: stay still for a second; the computation takes 1 to 3 s.",
            "Hauteur des nuages et effets => Cloud and effects height",
            "Tres haut => Very high",
            "Maillage ondulant => Wavy mesh",
            "Filaments => Filaments",
            "Barres et vagues => Bars and waves",
            "Hauteur de tes yeux debout (cm) => Your eye height standing (cm)",
            "Hauteur de tes yeux assis (cm) => Your eye height seated (cm)",
            "Sol ici : mes yeux sont a cette hauteur => Floor here: my eyes are at this height",
            "Suivi actif : les menus me suivent (non = ancres dans la piece) => Active follow: menus follow me (off = anchored in the room)",
            "Suivi actif : les menus et le clavier te suivent quand tu te deplaces (oui) ou restent ancres dans la piece (non) => Active follow: menus and keyboard follow you when you move (on) or stay anchored in the room (off)",
