            "Icone => Icono",
            "Icone, pourcentage, temps restant => Icono, porcentaje, tiempo restante",
            "Un PC fixe n'a pas de batterie : le dock affiche alors une prise (Secteur). Rien de tout cela ne tourne quand les trois cases sont decochees. => Un PC de sobremesa no tiene bateria: el dock muestra entonces un enchufe (Corriente). Nada de esto funciona con las tres casillas desmarcadas.",
            "Heure avec plein de cadrans, chronometre, minuteur et alarmes. => Hora con muchas esferas, cronometro, temporizador y alarmas.",
            "Heure avec plein de cadrans, chronometre, minuteur et alarmes (a renommer, AM / PM). Les alarmes sonnent meme application fermee. => Hora con muchas esferas, cronometro, temporizador y alarmas (renombrables, AM / PM). Las alarmas suenan aunque la aplicacion este cerrada.",
            "Principal => Principal",
            "Touche une valeur (balance, graves, medium, aigus) pour la remettre a zero. Limiteur : plafond 0 dB, doux des -3 dB. Le vumetre Principal est avant le limiteur : voyant rouge = ca sature. => Toca un valor (balance, graves, medios, agudos) para ponerlo a cero. Limitador: techo de 0 dB, suave desde -3 dB. El vumetro Principal esta antes del limitador: luz roja = esta saturando.",
            "   paupieres : gauche {0} %, droite {1} % =>    parpados: izquierdo {0} %, derecho {1} %",
            "Test => Prueba",
            "Ressenti => Sensacion",
            "Avancer dans le temps => Avanzar en el tiempo",
            "Effets de vent => Efectos de viento",
            "Vent dans le coin => Viento en la esquina",
            "Choisis ce que montre l'ecran Maintenant. Ce qui est cache ne coute rien. => Elige lo que muestra la pantalla Ahora. Lo que se oculta no cuesta nada.",
            "Cases d'information => Casillas de informacion",
            "Ecran Maintenant => Pantalla Ahora",
            "Voir et tester tous les temps (onglet Test) => Ver y probar todos los tipos de tiempo (pestana Prueba)",
            "Source : Windows (Wi-Fi / GPS) => Fuente: Windows (Wi-Fi / GPS)",
            "Source : adresse IP (approximatif) => Fuente: direccion IP (aproximado)",
            "Source : coordonnees saisies => Fuente: coordenadas escritas",
            "Source : ville choisie => Fuente: ciudad elegida",
            "Source : inconnue => Fuente: desconocida",
            "Pas encore de meteo. Verifie ta connexion internet ou choisis ta ville dans l'onglet Lieu. Les effets 3D se voient quand meme dans l'onglet Test. => Aun no hay tiempo. Revisa tu conexion a internet o elige tu ciudad en la pestana Lugar. Los efectos 3D se ven igualmente en la pestana Prueba.",
            "Un PC fixe n'a pas de GPS : Windows et internet ne donnent que la zone de ton fournisseur d'acces, parfois a des dizaines de km (la source est affichee en haut). Pour une position exacte, entre tes coordonnees ci-dessous ou cherche ta ville. => Un PC de sobremesa no tiene GPS: Windows e internet solo dan la zona de tu proveedor, a veces a decenas de km (la fuente se muestra arriba). Para una posicion exacta, escribe tus coordenadas abajo o busca tu ciudad.",
            "Coordonnees exactes (latitude, longitude) => Coordenadas exactas (latitud, longitud)",
            "Utiliser => Usar",
            "Coordonnees non valides. Exemple : 47.39, 0.68 => Coordenadas no validas. Ejemplo: 47.39, 0.68",
            "Astuce : sur une carte en ligne, clic droit sur ton adresse, puis copie les deux nombres (latitude puis longitude). => Consejo: en un mapa en linea, clic derecho en tu direccion y copia los dos numeros (latitud y luego longitud).",
            "Dans => En",
            "Lecture => Reproducir",
            "Pluie a cette heure => Lluvia a esta hora",
            "Vent {0} {1} => Viento {0} {1}",
            "Type de temps => Tipo de tiempo",
            "Conditions => Condiciones",
            "Heure du jour => Hora del dia",
            "Temperature => Temperatura",
            "Calme => Calma",
            "Brise => Brisa",
            "Vent fort => Viento fuerte",
            "Tempete => Tormenta",
            "Tour automatique des temps => Recorrido automatico de tiempos",
            "Le tour automatique passe tous les temps en revue, du ciel degage a l'orage et a la grele. Les curseurs changent l'heure (le soleil et la lune se deplacent), le vent (arbres, moulin, traits de vent) et la temperature (gel, canicule). => El recorrido automatico pasa por todos los tipos de tiempo, del cielo despejado a la tormenta y el granizo. Los controles cambian la hora (el sol y la luna se mueven), el viento (arboles, molino, rafagas) y la temperatura (helada, ola de calor).",
            "Assis : dock sous les yeux de (cm) => Sentado: dock bajo los ojos (cm)",
