            "Erreur :  => Error: ",
            "En marche : {0} x {1}, {2} img/s => En marcha: {0} x {1}, {2} img/s",
            "LED infrarouge : non utilisee => LED infrarroja: sin usar",
            "LED : choisis un menu d'appareil Bluetooth => LED: elige un menu de dispositivo Bluetooth",
            "LED : choisis le controle de ce menu => LED: elige el control de este menu",
            "LED : appareil Bluetooth pas connecte => LED: dispositivo Bluetooth no conectado",
            "LED : allumee => LED: encendida",
            "LED : eteinte => LED: apagada",
            "Cameras supplementaires => Camaras adicionales",
            "La camera normale (celle du tracking) ne change jamais. Ajoute ici une camera de vision nocturne, thermique ou autre (derriere ta tete...). Rien ne tourne tant qu'une camera n'est pas utilisee ; le bouton Vue du dock n'apparait que s'il y en a une activee. => La camara normal (la del seguimiento) nunca cambia. Anade aqui una camara de vision nocturna, termica u otra (detras de tu cabeza...). Nada funciona hasta que se usa una camara; el boton Vista del dock solo aparece si hay una activada.",
            "Cameras indisponibles => Camaras no disponibles",
            "Aucune camera : ajoutes-en une => Ninguna camara: anade una",
            "Ajouter une camera => Anadir una camara",
            "Supprimer cette camera => Eliminar esta camara",
            "Confirmer : supprimer => Confirmar: eliminar",
            "Cette camera => Esta camara",
            "Activee (bouton Vue du dock, application Miroir) => Activada (boton Vista del dock, app Espejo)",
            "Voir cette camera dans le casque maintenant => Ver esta camara en el casco ahora",
            "Source de l'image => Fuente de la imagen",
            "Camera USB => Camara USB",
            "Flux reseau (http) => Flujo de red (http)",
            "premiere camera => primera camara",
            "Actualiser la liste des cameras USB => Actualizar la lista de camaras USB",
            "Images par seconde => Fotogramas por segundo",
            "Ne choisis pas la camera du tracking : elle est deja utilisee par ar6dof_probe. => No elijas la camara del seguimiento: ar6dof_probe ya la usa.",
            "Adresse du flux d'images (MJPEG) => Direccion del flujo de imagenes (MJPEG)",
            "Une camera Wi-Fi (ESP32-CAM, camera IP...) qui envoie du MJPEG. Un identifiant se met dans l'adresse : http://nom:mot@adresse/flux. Le RTSP n'est pas gere. => Una camara Wi-Fi (ESP32-CAM, camara IP...) que envia MJPEG. Un usuario va en la direccion: http://nombre:clave@direccion/flujo. RTSP no es compatible.",
            "Contenu de l'image => Contenido de la imagen",
            "Echanger gauche / droite (si deux images) => Intercambiar izquierda / derecha (si hay dos imagenes)",
            "Image et IPD => Imagen e IPD",
            "Une seule image sert aux deux yeux (faux stereo : pas de relief). L'IPD ecarte ou rapproche l'image dans chaque oeil, comme l'IPD logiciel de l'image normale (les deux s'ajoutent). => Una sola imagen sirve a los dos ojos (falso estereo: sin relieve). La IPD separa o acerca la imagen en cada ojo, como la IPD de software de la imagen normal (las dos se suman).",
            "Champ de la camera (deg) => Campo de la camara (grados)",
            "IPD de cette camera (+ = ecarte) => IPD de esta camara (+ = separa)",
            "Delai de l'image (ms) => Retardo de la imagen (ms)",
            "Rotation => Rotacion",
            "Type de camera => Tipo de camara",
            "Gain (%) => Ganancia (%)",
            "Luminosite (%) => Brillo (%)",
            "Palette => Paleta",
            "Contraste (%) => Contraste (%)",
            "Niveau (%) => Nivel (%)",
            "Image affichee telle quelle : pour une camera libre (derriere la tete...), ouvre l'application Miroir. Une camera 'Autre' n'apparait pas dans le bouton Vue du dock. => Imagen mostrada tal cual: para una camara libre (detras de la cabeza...), abre la app Espejo. Una camara 'Otra' no aparece en el boton Vista del dock.",
            "Le suivi de position reste toujours sur la camera normale. L'effet (vert, palette) est applique par la carte graphique, sans cout quand la camera est arretee. => El seguimiento de posicion siempre se queda en la camara normal. El efecto (verde, paleta) lo aplica la tarjeta grafica, sin coste cuando la camara esta detenida.",
            "LED infrarouge => LED infrarroja",
            "Pour une camera de vision nocturne sans eclairage propre. Cree d'abord dans Apps > Nouvel appareil un menu Bluetooth pour ta LED, avec un curseur (puissance) ou un interrupteur, puis choisis-le ici. La LED s'allume seulement quand la camera tourne. => Para una camara de vision nocturna sin iluminacion propia. Crea primero en Apps > Nuevo dispositivo un menu Bluetooth para tu LED, con un control deslizante (potencia) o un interruptor, y eligelo aqui. La LED solo se enciende mientras la camara funciona.",
            "Allumer une LED infrarouge avec cette camera => Encender una LED infrarroja con esta camara",
            "Menu Bluetooth => Menu Bluetooth",
            "Controle => Control",
            "Puissance (%) => Potencia (%)",
            "Tester la LED => Probar la LED",
