            "Clique sur une etape puis prends l'expression tout de suite et garde-la\\n1,5 s. Les etapes 1 et 2 suffisent pour l'ouverture ; 3 et 4 reglent la\\nlargeur. Les valeurs sont lues dans Ar6dofMouthTracker.Instance.Mouth. => Klicke einen Schritt, mache sofort den Gesichtsausdruck und halte ihn\\n1,5 s. Schritt 1 und 2 reichen fuer die Oeffnung; 3 und 4 stellen die\\nBreite ein. Die Werte liest du in Ar6dofMouthTracker.Instance.Mouth.",
