            "En charge => Wird geladen",
            "Informations sur le dock => Dock-Informationen",
            "Afficher l'heure => Uhrzeit anzeigen",
            "Affichage de l'heure => Zeitanzeige",
            "Format 24 h (decoche : 12 h avec AM / PM) => 24-Stunden-Format (aus: 12 Std. mit AM / PM)",
            "Afficher la date => Datum anzeigen",
            "Afficher la batterie du PC => PC-Akku anzeigen",
            "Affichage de la batterie => Akkuanzeige",
            "Icone => Symbol",
            "Icone, pourcentage, temps restant => Symbol, Prozent, Restzeit",
            "Un PC fixe n'a pas de batterie : le dock affiche alors une prise (Secteur). Rien de tout cela ne tourne quand les trois cases sont decochees. => Ein Desktop-PC hat keinen Akku: Das Dock zeigt dann einen Stecker (Netzbetrieb). Nichts davon laeuft, wenn alle drei Haken entfernt sind.",
            "Heure avec plein de cadrans, chronometre, minuteur et alarmes. => Uhrzeit mit vielen Zifferblaettern, Stoppuhr, Timer und Wecker.",
            "Heure avec plein de cadrans, chronometre, minuteur et alarmes (a renommer, AM / PM). Les alarmes sonnent meme application fermee. => Uhrzeit mit vielen Zifferblaettern, Stoppuhr, Timer und Wecker (umbenennbar, AM / PM). Wecker klingeln auch bei geschlossener App.",
            "Principal => Master",
            "Touche une valeur (balance, graves, medium, aigus) pour la remettre a zero. Limiteur : plafond 0 dB, doux des -3 dB. Le vumetre Principal est avant le limiteur : voyant rouge = ca sature. => Tippe auf einen Wert (Balance, Bass, Mitten, Hoehen), um ihn auf null zu setzen. Limiter: Obergrenze 0 dB, weich ab -3 dB. Der Master-Pegel liegt vor dem Limiter: rotes Licht = es uebersteuert.",
            "   paupieres : gauche {0} %, droite {1} % =>    Augenlider: links {0} %, rechts {1} %",
            "Test => Test",
            "Ressenti => Gefuehlt",
            "Avancer dans le temps => In der Zeit vorspulen",
            "Effets de vent => Windeffekte",
            "Vent dans le coin => Wind in der Ecke",
            "Choisis ce que montre l'ecran Maintenant. Ce qui est cache ne coute rien. => Waehle, was der Bildschirm Jetzt zeigt. Was ausgeblendet ist, kostet nichts.",
            "Cases d'information => Infofelder",
            "Ecran Maintenant => Bildschirm Jetzt",
            "Voir et tester tous les temps (onglet Test) => Alle Wetterarten ansehen und testen (Reiter Test)",
            "Source : Windows (Wi-Fi / GPS) => Quelle: Windows (WLAN / GPS)",
            "Source : adresse IP (approximatif) => Quelle: IP-Adresse (ungefaehr)",
            "Source : coordonnees saisies => Quelle: eingegebene Koordinaten",
            "Source : ville choisie => Quelle: gewaehlte Stadt",
            "Source : inconnue => Quelle: unbekannt",
            "Pas encore de meteo. Verifie ta connexion internet ou choisis ta ville dans l'onglet Lieu. Les effets 3D se voient quand meme dans l'onglet Test. => Noch kein Wetter. Pruefe deine Internetverbindung oder waehle deine Stadt im Reiter Ort. Die 3D-Effekte siehst du trotzdem im Reiter Test.",
            "Un PC fixe n'a pas de GPS : Windows et internet ne donnent que la zone de ton fournisseur d'acces, parfois a des dizaines de km (la source est affichee en haut). Pour une position exacte, entre tes coordonnees ci-dessous ou cherche ta ville. => Ein Desktop-PC hat kein GPS: Windows und das Internet liefern nur die Gegend deines Anbieters, manchmal zig km entfernt (die Quelle steht oben). Fuer eine genaue Position gib unten deine Koordinaten ein oder suche deine Stadt.",
            "Coordonnees exactes (latitude, longitude) => Genaue Koordinaten (Breite, Laenge)",
            "Utiliser => Verwenden",
            "Coordonnees non valides. Exemple : 47.39, 0.68 => Ungueltige Koordinaten. Beispiel: 47.39, 0.68",
            "Astuce : sur une carte en ligne, clic droit sur ton adresse, puis copie les deux nombres (latitude puis longitude). => Tipp: Klicke auf einer Online-Karte mit rechts auf deine Adresse und kopiere die beiden Zahlen (erst Breite, dann Laenge).",
            "Dans => In",
            "Lecture => Abspielen",
            "Pluie a cette heure => Regen zu dieser Stunde",
            "Vent {0} {1} => Wind {0} {1}",
            "Type de temps => Wettertyp",
            "Conditions => Bedingungen",
            "Heure du jour => Tageszeit",
            "Temperature => Temperatur",
            "Calme => Windstill",
            "Brise => Brise",
            "Vent fort => Starker Wind",
            "Tempete => Sturm",
            "Tour automatique des temps => Automatische Wetterrunde",
            "Le tour automatique passe tous les temps en revue, du ciel degage a l'orage et a la grele. Les curseurs changent l'heure (le soleil et la lune se deplacent), le vent (arbres, moulin, traits de vent) et la temperature (gel, canicule). => Die automatische Runde zeigt alle Wetterarten, vom klaren Himmel bis zu Gewitter und Hagel. Die Regler aendern die Uhrzeit (Sonne und Mond wandern), den Wind (Baeume, Muehle, Windstreifen) und die Temperatur (Frost, Hitze).",
            "Assis : dock sous les yeux de (cm) => Sitzend: Dock unter den Augen (cm)",
            "Vue : Normale => Ansicht: Normal",
            "Vue => Ansicht",
            "Camera => Kamera",
            "Cameras => Kameras",
            "Vision nocturne => Nachtsicht",
            "Thermique => Waermebild",
            "Autre (retroviseur, miroir...) => Andere (Rueckspiegel, Spiegel...)",
            "Chaud = blanc => Heiss = weiss",
            "Chaud = noir => Heiss = schwarz",
            "Fer (noir, rouge, jaune) => Eisen (schwarz, rot, gelb)",
            "Blanc => Weiss",
            "Couleurs d'origine => Originalfarben",
            "Une seule image (faux stereo) => Ein Bild (Pseudo-Stereo)",
            "Deux images cote a cote => Zwei Bilder nebeneinander",
            "Deux images haut / bas => Zwei Bilder oben / unten",
            "Arretee (elle ne tourne que quand on s'en sert) => Gestoppt (laeuft nur, wenn sie benutzt wird)",
            "Erreur :  => Fehler: ",
            "En marche : {0} x {1}, {2} img/s => Laeuft: {0} x {1}, {2} Bilder/s",
            "LED infrarouge : non utilisee => Infrarot-LED: nicht benutzt",
            "LED : choisis un menu d'appareil Bluetooth => LED: waehle ein Bluetooth-Geraetemenue",
            "LED : choisis le controle de ce menu => LED: waehle das Steuerelement dieses Menues",
            "LED : appareil Bluetooth pas connecte => LED: Bluetooth-Geraet nicht verbunden",
            "LED : allumee => LED: an",
            "LED : eteinte => LED: aus",
            "Cameras supplementaires => Zusaetzliche Kameras",
            "La camera normale (celle du tracking) ne change jamais. Ajoute ici une camera de vision nocturne, thermique ou autre (derriere ta tete...). Rien ne tourne tant qu'une camera n'est pas utilisee ; le bouton Vue du dock n'apparait que s'il y en a une activee. => Die normale Kamera (die des Trackings) aendert sich nie. Fuege hier eine Nachtsicht-, Waermebild- oder andere Kamera hinzu (hinter dem Kopf...). Nichts laeuft, bis eine Kamera benutzt wird; die Ansicht-Taste im Dock erscheint nur, wenn eine aktiviert ist.",
            "Cameras indisponibles => Kameras nicht verfuegbar",
            "Aucune camera : ajoutes-en une => Keine Kamera: fuege eine hinzu",
            "Ajouter une camera => Kamera hinzufuegen",
            "Supprimer cette camera => Diese Kamera loeschen",
            "Confirmer : supprimer => Bestaetigen: loeschen",
            "Cette camera => Diese Kamera",
            "Activee (bouton Vue du dock, application Miroir) => Aktiviert (Ansicht-Taste im Dock, Spiegel-App)",
            "Voir cette camera dans le casque maintenant => Diese Kamera jetzt im Headset ansehen",
            "Source de l'image => Bildquelle",
            "Camera USB => USB-Kamera",
            "Flux reseau (http) => Netzwerk-Stream (http)",
            "premiere camera => erste Kamera",
            "Actualiser la liste des cameras USB => USB-Kameraliste aktualisieren",
            "Images par seconde => Bilder pro Sekunde",
            "Ne choisis pas la camera du tracking : elle est deja utilisee par ar6dof_probe. => Waehle nicht die Tracking-Kamera: ar6dof_probe benutzt sie bereits.",
            "Adresse du flux d'images (MJPEG) => Adresse des Bildstroms (MJPEG)",
            "Une camera Wi-Fi (ESP32-CAM, camera IP...) qui envoie du MJPEG. Un identifiant se met dans l'adresse : http://nom:mot@adresse/flux. Le RTSP n'est pas gere. => Eine WLAN-Kamera (ESP32-CAM, IP-Kamera...), die MJPEG sendet. Ein Login steht in der Adresse: http://name:passwort@adresse/stream. RTSP wird nicht unterstuetzt.",
            "Contenu de l'image => Bildinhalt",
            "Echanger gauche / droite (si deux images) => Links / rechts tauschen (bei zwei Bildern)",
            "Image et IPD => Bild und IPD",
            "Une seule image sert aux deux yeux (faux stereo : pas de relief). L'IPD ecarte ou rapproche l'image dans chaque oeil, comme l'IPD logiciel de l'image normale (les deux s'ajoutent). => Ein einziges Bild dient beiden Augen (Pseudo-Stereo: keine Tiefe). Die IPD schiebt das Bild in jedem Auge auseinander oder zusammen, wie die Software-IPD des normalen Bildes (beide addieren sich).",
            "Champ de la camera (deg) => Sichtfeld der Kamera (Grad)",
            "IPD de cette camera (+ = ecarte) => IPD dieser Kamera (+ = auseinander)",
            "Delai de l'image (ms) => Bildverzoegerung (ms)",
            "Rotation => Drehung",
            "Type de camera => Kameratyp",
            "Gain (%) => Verstaerkung (%)",
            "Luminosite (%) => Helligkeit (%)",
            "Palette => Palette",
            "Contraste (%) => Kontrast (%)",
            "Niveau (%) => Pegel (%)",
            "Image affichee telle quelle : pour une camera libre (derriere la tete...), ouvre l'application Miroir. Une camera 'Autre' n'apparait pas dans le bouton Vue du dock. => Bild unverandert angezeigt: fuer eine freie Kamera (hinter dem Kopf...) oeffne die Spiegel-App. Eine Kamera 'Andere' erscheint nicht in der Ansicht-Taste des Docks.",
            "Le suivi de position reste toujours sur la camera normale. L'effet (vert, palette) est applique par la carte graphique, sans cout quand la camera est arretee. => Das Positionstracking bleibt immer auf der normalen Kamera. Der Effekt (gruen, Palette) wird von der Grafikkarte angewendet, ohne Kosten bei gestoppter Kamera.",
            "LED infrarouge => Infrarot-LED",
            "Pour une camera de vision nocturne sans eclairage propre. Cree d'abord dans Apps > Nouvel appareil un menu Bluetooth pour ta LED, avec un curseur (puissance) ou un interrupteur, puis choisis-le ici. La LED s'allume seulement quand la camera tourne. => Fuer eine Nachtsichtkamera ohne eigene Beleuchtung. Erstelle zuerst unter Apps > Neues Geraet ein Bluetooth-Menue fuer deine LED mit Schieberegler (Leistung) oder Schalter und waehle es hier. Die LED leuchtet nur, solange die Kamera laeuft.",
            "Allumer une LED infrarouge avec cette camera => Eine Infrarot-LED mit dieser Kamera einschalten",
            "Menu Bluetooth => Bluetooth-Menue",
            "Controle => Steuerelement",
            "Puissance (%) => Leistung (%)",
            "Tester la LED => LED testen",
            "Eteindre la LED (test) => LED ausschalten (Test)",
            "Une camera libre (derriere ta tete...) dans une fenetre => Eine freie Kamera (hinter deinem Kopf...) in einem Fenster",
            "Une camera libre (derriere ta tete, sur la queue...) dans une fenetre : effet miroir, retournement, taille. Elle ne tourne que fenetre affichee. => Eine freie Kamera (hinter dem Kopf, am Schwanz...) in einem Fenster: Spiegeleffekt, Drehen, Groesse. Sie laeuft nur, solange das Fenster sichtbar ist.",
            "Aucune camera n'est activee. Ajoute-en une dans Reglages > Image > Cameras (camera USB ou flux reseau), par exemple celle placee derriere ta tete. => Keine Kamera ist aktiviert. Fuege in Einstellungen > Bild > Kameras eine hinzu (USB-Kamera oder Netzwerk-Stream), zum Beispiel die hinter deinem Kopf.",
            "Effet miroir : oui => Spiegeleffekt: ja",
            "Effet miroir : non => Spiegeleffekt: nein",
            "Retourne : oui => Gedreht: ja",
            "Retourne : non => Gedreht: nein",
            "Petit => Klein",
            "Moyen => Mittel",
            "Grand => Gross",
            "Pour regler la camera (source, image, vision nocturne, LED...) : Reglages > Image > Cameras. La camera s'arrete quand cette fenetre est rangee. => Zum Einrichten der Kamera (Quelle, Bild, Nachtsicht, LED...): Einstellungen > Bild > Kameras. Die Kamera stoppt, wenn dieses Fenster weggelegt wird.",
            "Plus => Mehr",
            "Ville estimee par internet (peut etre fausse) => Stadt per Internet geschaetzt (kann falsch sein)",
            "Source : position saisie => Quelle: eingegebene Position",
            "Ce n'est pas ma ville ? Choisir ma ville => Nicht meine Stadt? Meine Stadt waehlen",
            "Ma ville => Meine Stadt",
            "Cherche ta ville, choisis-la dans la liste : elle est gardee, et plus jamais remplacee par une estimation. Aucune coordonnee n'est affichee. => Suche deine Stadt und waehle sie in der Liste: sie bleibt gespeichert und wird nie durch eine Schaetzung ersetzt. Es werden keine Koordinaten angezeigt.",
            "Position automatique => Automatische Position",
            "Utiliser la position de Windows (Wi-Fi / GPS) => Windows-Standort verwenden (WLAN / GPS)",
            "Estimer par internet => Per Internet schaetzen",
            "Un PC fixe n'a pas de GPS : Windows et internet ne donnent que la zone de ton fournisseur d'acces, parfois a des dizaines de km. La position est arrondie a 1 km environ et jamais affichee. => Ein Desktop-PC hat kein GPS: Windows und das Internet liefern nur das Gebiet deines Anbieters, manchmal Dutzende km entfernt. Die Position wird auf etwa 1 km gerundet und nie angezeigt.",
            "Coordonnees (avance) => Koordinaten (erweitert)",
            "latitude, longitude => Breitengrad, Laengengrad",
            "Ma position => Meine Position",
            "Scene 3D => 3D-Szene",
            "Hauteur de l'ile => Hoehe der Insel",
            "Taille du cadre => Rahmengroesse",
            "Comme avant => Wie vorher",
            "Un peu plus bas => Etwas tiefer",
            "Plus bas => Tiefer",
            "Tres bas => Sehr tief",
            "Page Plus => Seite Mehr",
            "Page Plus (tester tous les temps) => Seite Mehr (alle Wetterlagen testen)",
            "La page Plus permet de voir tous les types de temps a la main (heure, vent, temperature). Elle reste cachee tant que tu ne l'actives pas. => Auf der Seite Mehr kannst du alle Wetterarten von Hand ansehen (Uhrzeit, Wind, Temperatur). Sie bleibt versteckt, bis du sie aktivierst.",
            "Ouvrir la page Plus => Seite Mehr oeffnen",
            "Alchimie => Alchemie",
            "Ambiance => Ambiente",
            "Cubes => Wuerfel",
            "Particules => Partikel",
            "Tunnel => Tunnel",
            "Pics => Spitzen",
            "Feux d'artifice => Feuerwerk",
            "Couleurs musicales => Musikalische Farben",
            "Toile => Netz",
            "Clic : agrandir / reduire => Klick: vergroessern / verkleinern",
            "DJ => DJ",
            "Boucle => Loop",
            "Charger... => Laden...",
            "Ejecter => Auswerfen",
            "Filtre => Filter",
            "Crossfader => Crossfader",
            "Mix => Mix",
            "Coupe => Cut",
            "Chargement... => Laedt...",
            "Aucune piste : Charger... => Kein Titel: Laden...",
            "BPM inconnu => BPM unbekannt",
            "Charger dans la platine A => In Deck A laden",
            "Charger dans la platine B => In Deck B laden",
            "La liste est vide. Ajoute des musiques (elles sont aussi dans l'onglet Musique). => Die Liste ist leer. Fuege Musik hinzu (sie ist auch im Tab Musik).",
            "Retour aux platines => Zurueck zu den Decks",
            "Une piste est lue en entier (10 minutes au maximum). L'analyse du tempo prend quelques secondes. => Ein Titel wird komplett eingelesen (maximal 10 Minuten). Die Tempoanalyse dauert einige Sekunden.",
            "Les pistes sortent par la tranche Musique (son general inclus). Le tempo change aussi la hauteur du son (comme un tourne-disque). Les reperes ne sont pas gardes. => Titel laufen ueber den Musik-Kanal (Hauptausgang inklusive). Das Tempo aendert auch die Tonhoehe (wie ein Plattenspieler). Cue-Punkte werden nicht gespeichert.",
            "Tempo 0 => Tempo 0",
            "Piste precedente => Vorheriger Titel",
            "Piste suivante => Naechster Titel",
            "Lire / Pause => Wiedergabe / Pause",
            "Notifications => Benachrichtigungen",
            "Alarmes, evenements, problemes et musique en cours => Wecker, Termine, Probleme und laufende Musik",
            "Musique en cours => Aktuelle Musik",
            "Rien a signaler. => Nichts zu melden.",
            "Effacer => Loeschen",
            "Tout effacer => Alle loeschen",
            "Connexion perdue => Verbindung verloren",
            "Plus de donnees du casque (ar6dof_probe lance ?) => Keine Daten mehr vom Headset (laeuft ar6dof_probe?)",
            "Suivi perdu => Tracking verloren",
            "Le suivi de la tete ne fonctionne plus => Das Kopf-Tracking funktioniert nicht mehr",
            "Calendrier => Kalender",
            "Evenement => Termin",
            "Dans {0} min => In {0} Min.",
            "Evenements avec rappel avant leur debut, et scan d'une affiche ou d'un programme de convention. => Termine mit Erinnerung vor Beginn und Scan eines Plakats oder Convention-Programms.",
            "Evenements avec rappel avant leur debut. Scanne une affiche ou le programme d'une convention devant toi pour les creer. Le scan ne tourne que quand tu le lances. => Termine mit Erinnerung vor Beginn. Scanne ein Plakat oder Convention-Programm vor dir, um sie anzulegen. Der Scan laeuft nur, wenn du ihn startest.",
            "Calendrier indisponible. => Kalender nicht verfuegbar.",
            "Agenda => Agenda",
            "Scanner => Scannen",
            "(sans rappel) => (ohne Erinnerung)",
            "Ajouter un evenement => Termin hinzufuegen",
            "Aucun evenement. Va dans Scanner pour lire une affiche ou un programme, ou ajoute-en un a la main. => Keine Termine. Gehe zu Scannen, um ein Plakat oder Programm zu lesen, oder fuege einen von Hand hinzu.",
            "Nouvel evenement => Neuer Termin",
            "Modifier l'evenement => Termin bearbeiten",
            "Nom de l'evenement => Name des Termins",
            "Lieu (facultatif) => Ort (optional)",
            "Duree inconnue => Dauer unbekannt",
            "Duree => Dauer",
            "Rappel avant le debut => Erinnerung vor Beginn",
            "Le rappel sonne {0} min avant (a regler dans Options). => Die Erinnerung klingelt {0} Min. vorher (einstellbar unter Optionen).",
            "Tiens l'affiche ou le programme bien en face de toi, texte lisible et bien eclaire, sans bouger. Touche Lancer : photo dans 3 secondes, lecture du texte par Windows, puis tu relis les evenements avant de les enregistrer. Rien ne tourne avant ton clic. => Halte das Plakat oder Programm direkt vor dich, Text lesbar und gut beleuchtet, ohne dich zu bewegen. Tippe auf Starten: Foto in 3 Sekunden, Windows liest den Text, dann pruefst du die Termine vor dem Speichern. Vor deinem Klick laeuft nichts.",
            "Lancer le scan => Scan starten",
            "Scan dans {0} s... => Scan in {0} s...",
            "Photo... => Foto...",
            "Lecture du texte... => Text wird gelesen...",
            "Camera indisponible : le passthrough n'est pas pret => Kamera nicht verfuegbar: Passthrough nicht bereit",
            "Photo impossible : {0} => Foto fehlgeschlagen: {0}",
            "Photo impossible : rien n'a ete enregistre => Foto fehlgeschlagen: nichts wurde gespeichert",
            "Aucun horaire reconnu. Rapproche-toi, ameliore la lumiere, ou regarde le texte lu ci-dessous. => Keine Uhrzeit erkannt. Geh naeher heran, verbessere das Licht oder sieh dir den gelesenen Text unten an.",
            "{0} evenement(s) trouve(s). Decoche ceux que tu ne veux pas, touche une ligne pour corriger. => {0} Termin(e) gefunden. Entferne das Haekchen bei unerwuenschten, tippe auf eine Zeile zum Korrigieren.",
            "Enregistrer ({0}) => Speichern ({0})",
            "Nouveau scan => Neuer Scan",
            "Cacher le texte lu => Gelesenen Text ausblenden",
            "Voir le texte lu => Gelesenen Text anzeigen",
            "Aucun texte lu. => Kein Text gelesen.",
            "Rien de nouveau a enregistrer => Nichts Neues zu speichern",
            "{0} evenement(s) ajoute(s) => {0} Termin(e) hinzugefuegt",
            "Rappel => Erinnerung",
            "Le rappel sonne avant le debut de l'evenement : => Die Erinnerung klingelt vor Beginn des Termins:",
            "Le rappel passe par la sonnerie de l'horloge et laisse une ligne dans les notifications. Il sonne meme si cette fenetre est fermee. => Die Erinnerung nutzt den Klingelton der Uhr und hinterlaesst eine Zeile in den Benachrichtigungen. Sie klingelt auch bei geschlossenem Fenster.",
            "Scan => Scan",
            "La photo du scan est lue par Windows sur ton PC (rien n'est envoye sur Internet), puis supprimee tout de suite. => Das Scan-Foto wird von Windows auf deinem PC gelesen (nichts wird ins Internet gesendet) und sofort geloescht.",
            "Donnees => Daten",
            "Confirmer : tout effacer ? => Bestaetigen: alles loeschen?",
            "Effacer tous les evenements => Alle Termine loeschen",
            "Delai depasse (la lecture du texte a pris plus de 45 s) => Zeitueberschreitung (das Lesen des Textes dauerte ueber 45 s)",
            "Aucune langue avec reconnaissance de texte dans Windows (Parametres > Heure et langue > Langue : ajoute le francais) => Keine Sprache mit Texterkennung in Windows (Einstellungen > Zeit und Sprache > Sprache: Franzoesisch hinzufuegen)",
            "Qualite : normale => Qualitaet: normal",
            "Qualite : 8 images accumulees => Qualitaet: 8 Bilder gestapelt",
            "Qualite : 8 images, grille x2 => Qualitaet: 8 Bilder, Raster x2",
            "Accumulation : reste immobile une seconde ; le calcul prend 1 a 3 s. => Stapeln: bleib eine Sekunde ruhig; die Berechnung dauert 1 bis 3 s.",
            "Hauteur des nuages et effets => Hoehe von Wolken und Effekten",
