            "Icone => Icona",
            "Icone, pourcentage, temps restant => Icona, percentuale, tempo rimasto",
            "Un PC fixe n'a pas de batterie : le dock affiche alors une prise (Secteur). Rien de tout cela ne tourne quand les trois cases sont decochees. => Un PC fisso non ha la batteria: il dock mostra allora una presa (Alimentazione di rete). Niente di tutto questo e attivo con le tre caselle deselezionate.",
            "Heure avec plein de cadrans, chronometre, minuteur et alarmes. => Ora con tanti quadranti, cronometro, timer e sveglie.",
            "Heure avec plein de cadrans, chronometre, minuteur et alarmes (a renommer, AM / PM). Les alarmes sonnent meme application fermee. => Ora con tanti quadranti, cronometro, timer e sveglie (rinominabili, AM / PM). Le sveglie suonano anche con l'app chiusa.",
            "Principal => Principale",
            "Touche une valeur (balance, graves, medium, aigus) pour la remettre a zero. Limiteur : plafond 0 dB, doux des -3 dB. Le vumetre Principal est avant le limiteur : voyant rouge = ca sature. => Tocca un valore (bilanciamento, bassi, medi, alti) per azzerarlo. Limiter: tetto a 0 dB, morbido da -3 dB. Il vu-meter Principale e prima del limiter: luce rossa = sta saturando.",
            "   paupieres : gauche {0} %, droite {1} % =>    palpebre: sinistra {0} %, destra {1} %",
            "Test => Prova",
