            "Source : coordonnees saisies => Fonte: coordinate inserite",
            "Source : ville choisie => Fonte: citta scelta",
            "Source : inconnue => Fonte: sconosciuta",
            "Pas encore de meteo. Verifie ta connexion internet ou choisis ta ville dans l'onglet Lieu. Les effets 3D se voient quand meme dans l'onglet Test. => Ancora nessun meteo. Controlla la connessione a internet o scegli la citta nella scheda Luogo. Gli effetti 3D si vedono comunque nella scheda Prova.",
            "Un PC fixe n'a pas de GPS : Windows et internet ne donnent que la zone de ton fournisseur d'acces, parfois a des dizaines de km (la source est affichee en haut). Pour une position exacte, entre tes coordonnees ci-dessous ou cherche ta ville. => Un PC fisso non ha il GPS: Windows e internet danno solo la zona del tuo provider, a volte a decine di km (la fonte e indicata in alto). Per una posizione esatta, inserisci le coordinate qui sotto o cerca la tua citta.",
            "Coordonnees exactes (latitude, longitude) => Coordinate esatte (latitudine, longitudine)",
            "Utiliser => Usa",
            "Coordonnees non valides. Exemple : 47.39, 0.68 => Coordinate non valide. Esempio: 47.39, 0.68",
            "Astuce : sur une carte en ligne, clic droit sur ton adresse, puis copie les deux nombres (latitude puis longitude). => Suggerimento: su una mappa online, clic destro sul tuo indirizzo e copia i due numeri (prima latitudine, poi longitudine).",
            "Dans => Tra",
            "Lecture => Riproduci",
            "Pluie a cette heure => Pioggia a quest'ora",
            "Vent {0} {1} => Vento {0} {1}",
            "Type de temps => Tipo di tempo",
            "Conditions => Condizioni",
            "Heure du jour => Ora del giorno",
            "Temperature => Temperatura",
            "Calme => Calmo",
            "Brise => Brezza",
            "Vent fort => Vento forte",
            "Tempete => Tempesta",
            "Tour automatique des temps => Giro automatico dei tempi",
            "Le tour automatique passe tous les temps en revue, du ciel degage a l'orage et a la grele. Les curseurs changent l'heure (le soleil et la lune se deplacent), le vent (arbres, moulin, traits de vent) et la temperature (gel, canicule). => Il giro automatico passa in rassegna tutti i tempi, dal cielo sereno al temporale con grandine. I cursori cambiano l'ora (sole e luna si spostano), il vento (alberi, mulino, scie di vento) e la temperatura (gelo, caldo).",
            "Assis : dock sous les yeux de (cm) => Seduto: dock sotto gli occhi di (cm)",
