            "LED : choisis le controle de ce menu => LED: scegli il controllo di questo menu",
            "LED : appareil Bluetooth pas connecte => LED: dispositivo Bluetooth non connesso",
            "LED : allumee => LED: accesa",
            "LED : eteinte => LED: spenta",
            "Cameras supplementaires => Fotocamere aggiuntive",
            "La camera normale (celle du tracking) ne change jamais. Ajoute ici une camera de vision nocturne, thermique ou autre (derriere ta tete...). Rien ne tourne tant qu'une camera n'est pas utilisee ; le bouton Vue du dock n'apparait que s'il y en a une activee. => La fotocamera normale (quella del tracking) non cambia mai. Aggiungi qui una fotocamera a visione notturna, termica o altra (dietro la testa...). Niente funziona finche una fotocamera non e usata; il pulsante Vista del dock compare solo se ce n'e una attiva.",
            "Cameras indisponibles => Fotocamere non disponibili",
