            "Voir cette camera dans le casque maintenant => Vedi ora questa fotocamera nel visore",
            "Source de l'image => Sorgente dell'immagine",
            "Camera USB => Fotocamera USB",
            "Flux reseau (http) => Flusso di rete (http)",
            "premiere camera => prima fotocamera",
            "Actualiser la liste des cameras USB => Aggiorna l'elenco delle fotocamere USB",
            "Images par seconde => Fotogrammi al secondo",
            "Ne choisis pas la camera du tracking : elle est deja utilisee par ar6dof_probe. => Non scegliere la fotocamera del tracking: ar6dof_probe la usa gia.",
            "Adresse du flux d'images (MJPEG) => Indirizzo del flusso di immagini (MJPEG)",
            "Une camera Wi-Fi (ESP32-CAM, camera IP...) qui envoie du MJPEG. Un identifiant se met dans l'adresse : http://nom:mot@adresse/flux. Le RTSP n'est pas gere. => Una fotocamera Wi-Fi (ESP32-CAM, telecamera IP...) che invia MJPEG. Le credenziali vanno nell'indirizzo: http://nome:pass@indirizzo/flusso. L'RTSP non e supportato.",
            "Contenu de l'image => Contenuto dell'immagine",
