            "Format 24 h (decoche : 12 h avec AM / PM) => Formato de 24 h (desmarcado: 12 h com AM / PM)",
            "Afficher la date => Mostrar a data",
            "Afficher la batterie du PC => Mostrar a bateria do PC",
            "Affichage de la batterie => Exibicao da bateria",
            "Icone => Icone",
            "Icone, pourcentage, temps restant => Icone, porcentagem, tempo restante",
            "Un PC fixe n'a pas de batterie : le dock affiche alors une prise (Secteur). Rien de tout cela ne tourne quand les trois cases sont decochees. => Um PC de mesa nao tem bateria: o dock mostra entao uma tomada (Energia da tomada). Nada disso funciona com as tres caixas desmarcadas.",
            "Heure avec plein de cadrans, chronometre, minuteur et alarmes. => Hora com varios mostradores, cronometro, temporizador e alarmes.",
            "Heure avec plein de cadrans, chronometre, minuteur et alarmes (a renommer, AM / PM). Les alarmes sonnent meme application fermee. => Hora com varios mostradores, cronometro, temporizador e alarmes (renomeaveis, AM / PM). Os alarmes tocam mesmo com o aplicativo fechado.",
            "Principal => Principal",
            "Touche une valeur (balance, graves, medium, aigus) pour la remettre a zero. Limiteur : plafond 0 dB, doux des -3 dB. Le vumetre Principal est avant le limiteur : voyant rouge = ca sature. => Toque num valor (balanco, graves, medios, agudos) para zera-lo. Limitador: teto de 0 dB, suave a partir de -3 dB. O vumetro Principal fica antes do limitador: luz vermelha = esta saturando.",
            "   paupieres : gauche {0} %, droite {1} % =>    palpebras: esquerda {0} %, direita {1} %",
            "Test => Teste",
            "Ressenti => Sensacao",
            "Avancer dans le temps => Avancar no tempo",
            "Effets de vent => Efeitos de vento",
            "Vent dans le coin => Vento no canto",
            "Choisis ce que montre l'ecran Maintenant. Ce qui est cache ne coute rien. => Escolha o que a tela Agora mostra. O que fica oculto nao custa nada.",
            "Cases d'information => Caixas de informacao",
            "Ecran Maintenant => Tela Agora",
            "Voir et tester tous les temps (onglet Test) => Ver e testar todos os tipos de tempo (aba Teste)",
            "Source : Windows (Wi-Fi / GPS) => Fonte: Windows (Wi-Fi / GPS)",
            "Source : adresse IP (approximatif) => Fonte: endereco IP (aproximado)",
            "Source : coordonnees saisies => Fonte: coordenadas digitadas",
            "Source : ville choisie => Fonte: cidade escolhida",
            "Source : inconnue => Fonte: desconhecida",
            "Pas encore de meteo. Verifie ta connexion internet ou choisis ta ville dans l'onglet Lieu. Les effets 3D se voient quand meme dans l'onglet Test. => Ainda sem tempo. Verifique sua conexao com a internet ou escolha sua cidade na aba Local. Os efeitos 3D aparecem mesmo assim na aba Teste.",
            "Un PC fixe n'a pas de GPS : Windows et internet ne donnent que la zone de ton fournisseur d'acces, parfois a des dizaines de km (la source est affichee en haut). Pour une position exacte, entre tes coordonnees ci-dessous ou cherche ta ville. => Um PC de mesa nao tem GPS: o Windows e a internet so informam a regiao do seu provedor, as vezes a dezenas de km (a fonte aparece no alto). Para uma posicao exata, digite suas coordenadas abaixo ou procure sua cidade.",
            "Coordonnees exactes (latitude, longitude) => Coordenadas exatas (latitude, longitude)",
            "Utiliser => Usar",
            "Coordonnees non valides. Exemple : 47.39, 0.68 => Coordenadas invalidas. Exemplo: 47.39, 0.68",
            "Astuce : sur une carte en ligne, clic droit sur ton adresse, puis copie les deux nombres (latitude puis longitude). => Dica: em um mapa online, clique com o botao direito no seu endereco e copie os dois numeros (latitude e depois longitude).",
            "Dans => Em",
            "Lecture => Reproduzir",
            "Pluie a cette heure => Chuva nesta hora",
            "Vent {0} {1} => Vento {0} {1}",
            "Type de temps => Tipo de tempo",
            "Conditions => Condicoes",
            "Heure du jour => Hora do dia",
            "Temperature => Temperatura",
            "Calme => Calmo",
            "Brise => Brisa",
            "Vent fort => Vento forte",
            "Tempete => Tempestade",
            "Tour automatique des temps => Passeio automatico dos tempos",
            "Le tour automatique passe tous les temps en revue, du ciel degage a l'orage et a la grele. Les curseurs changent l'heure (le soleil et la lune se deplacent), le vent (arbres, moulin, traits de vent) et la temperature (gel, canicule). => O passeio automatico percorre todos os tempos, do ceu limpo a tempestade e ao granizo. Os controles mudam a hora (o sol e a lua se movem), o vento (arvores, moinho, rastros de vento) e a temperatura (geada, onda de calor).",
            "Assis : dock sous les yeux de (cm) => Sentado: dock abaixo dos olhos (cm)",
            "Vue : Normale => Vista: Normal",
            "Vue => Vista",
            "Camera => Camera",
            "Cameras => Cameras",
            "Vision nocturne => Visao noturna",
            "Thermique => Termica",
            "Autre (retroviseur, miroir...) => Outra (retrovisor, espelho...)",
            "Chaud = blanc => Quente = branco",
            "Chaud = noir => Quente = preto",
            "Fer (noir, rouge, jaune) => Ferro (preto, vermelho, amarelo)",
            "Blanc => Branco",
            "Couleurs d'origine => Cores originais",
            "Une seule image (faux stereo) => Uma so imagem (falso estereo)",
            "Deux images cote a cote => Duas imagens lado a lado",
            "Deux images haut / bas => Duas imagens em cima / embaixo",
            "Arretee (elle ne tourne que quand on s'en sert) => Parada (so funciona quando em uso)",
            "Erreur :  => Erro: ",
            "En marche : {0} x {1}, {2} img/s => Funcionando: {0} x {1}, {2} img/s",
            "LED infrarouge : non utilisee => LED infravermelho: nao usado",
            "LED : choisis un menu d'appareil Bluetooth => LED: escolha um menu de dispositivo Bluetooth",
            "LED : choisis le controle de ce menu => LED: escolha o controle deste menu",
            "LED : appareil Bluetooth pas connecte => LED: dispositivo Bluetooth nao conectado",
            "LED : allumee => LED: acesa",
            "LED : eteinte => LED: apagada",
            "Cameras supplementaires => Cameras adicionais",
            "La camera normale (celle du tracking) ne change jamais. Ajoute ici une camera de vision nocturne, thermique ou autre (derriere ta tete...). Rien ne tourne tant qu'une camera n'est pas utilisee ; le bouton Vue du dock n'apparait que s'il y en a une activee. => A camera normal (a do rastreamento) nunca muda. Adicione aqui uma camera de visao noturna, termica ou outra (atras da cabeca...). Nada roda ate uma camera ser usada; o botao Vista do dock so aparece se houver uma ativada.",
            "Cameras indisponibles => Cameras indisponiveis",
            "Aucune camera : ajoutes-en une => Nenhuma camera: adicione uma",
            "Ajouter une camera => Adicionar uma camera",
            "Supprimer cette camera => Excluir esta camera",
            "Confirmer : supprimer => Confirmar: excluir",
            "Cette camera => Esta camera",
            "Activee (bouton Vue du dock, application Miroir) => Ativada (botao Vista do dock, app Espelho)",
            "Voir cette camera dans le casque maintenant => Ver esta camera no headset agora",
            "Source de l'image => Fonte da imagem",
            "Camera USB => Camera USB",
            "Flux reseau (http) => Fluxo de rede (http)",
            "premiere camera => primeira camera",
            "Actualiser la liste des cameras USB => Atualizar a lista de cameras USB",
            "Images par seconde => Quadros por segundo",
            "Ne choisis pas la camera du tracking : elle est deja utilisee par ar6dof_probe. => Nao escolha a camera do rastreamento: o ar6dof_probe ja a usa.",
            "Adresse du flux d'images (MJPEG) => Endereco do fluxo de imagens (MJPEG)",
            "Une camera Wi-Fi (ESP32-CAM, camera IP...) qui envoie du MJPEG. Un identifiant se met dans l'adresse : http://nom:mot@adresse/flux. Le RTSP n'est pas gere. => Uma camera Wi-Fi (ESP32-CAM, camera IP...) que envia MJPEG. O login vai no endereco: http://nome:senha@endereco/fluxo. RTSP nao e suportado.",
            "Contenu de l'image => Conteudo da imagem",
            "Echanger gauche / droite (si deux images) => Trocar esquerda / direita (se duas imagens)",
            "Image et IPD => Imagem e IPD",
            "Une seule image sert aux deux yeux (faux stereo : pas de relief). L'IPD ecarte ou rapproche l'image dans chaque oeil, comme l'IPD logiciel de l'image normale (les deux s'ajoutent). => Uma so imagem serve aos dois olhos (falso estereo: sem relevo). O IPD afasta ou aproxima a imagem em cada olho, como o IPD de software da imagem normal (os dois se somam).",
            "Champ de la camera (deg) => Campo da camera (graus)",
            "IPD de cette camera (+ = ecarte) => IPD desta camera (+ = afasta)",
            "Delai de l'image (ms) => Atraso da imagem (ms)",
            "Rotation => Rotacao",
            "Type de camera => Tipo de camera",
            "Gain (%) => Ganho (%)",
            "Luminosite (%) => Brilho (%)",
            "Palette => Paleta",
            "Contraste (%) => Contraste (%)",
            "Niveau (%) => Nivel (%)",
            "Image affichee telle quelle : pour une camera libre (derriere la tete...), ouvre l'application Miroir. Une camera 'Autre' n'apparait pas dans le bouton Vue du dock. => Imagem mostrada como esta: para uma camera livre (atras da cabeca...), abra o app Espelho. Uma camera 'Outra' nao aparece no botao Vista do dock.",
            "Le suivi de position reste toujours sur la camera normale. L'effet (vert, palette) est applique par la carte graphique, sans cout quand la camera est arretee. => O rastreamento de posicao fica sempre na camera normal. O efeito (verde, paleta) e aplicado pela placa de video, sem custo quando a camera esta parada.",
            "LED infrarouge => LED infravermelho",
            "Pour une camera de vision nocturne sans eclairage propre. Cree d'abord dans Apps > Nouvel appareil un menu Bluetooth pour ta LED, avec un curseur (puissance) ou un interrupteur, puis choisis-le ici. La LED s'allume seulement quand la camera tourne. => Para uma camera de visao noturna sem iluminacao propria. Crie primeiro em Apps > Novo dispositivo um menu Bluetooth para o seu LED, com um controle deslizante (potencia) ou um interruptor, e escolha-o aqui. O LED so acende enquanto a camera funciona.",
            "Allumer une LED infrarouge avec cette camera => Acender um LED infravermelho com esta camera",
            "Menu Bluetooth => Menu Bluetooth",
            "Controle => Controle",
            "Puissance (%) => Potencia (%)",
            "Tester la LED => Testar o LED",
            "Eteindre la LED (test) => Apagar o LED (teste)",
            "Une camera libre (derriere ta tete...) dans une fenetre => Uma camera livre (atras da sua cabeca...) numa janela",
            "Une camera libre (derriere ta tete, sur la queue...) dans une fenetre : effet miroir, retournement, taille. Elle ne tourne que fenetre affichee. => Uma camera livre (atras da cabeca, na cauda...) numa janela: efeito espelho, inversao, tamanho. So funciona com a janela visivel.",
            "Aucune camera n'est activee. Ajoute-en une dans Reglages > Image > Cameras (camera USB ou flux reseau), par exemple celle placee derriere ta tete. => Nenhuma camera esta ativada. Adicione uma em Configuracoes > Imagem > Cameras (camera USB ou fluxo de rede), por exemplo a de tras da cabeca.",
            "Effet miroir : oui => Efeito espelho: sim",
            "Effet miroir : non => Efeito espelho: nao",
            "Retourne : oui => Invertido: sim",
            "Retourne : non => Invertido: nao",
            "Petit => Pequeno",
            "Moyen => Medio",
            "Grand => Grande",
            "Pour regler la camera (source, image, vision nocturne, LED...) : Reglages > Image > Cameras. La camera s'arrete quand cette fenetre est rangee. => Para configurar a camera (fonte, imagem, visao noturna, LED...): Configuracoes > Imagem > Cameras. A camera para quando esta janela e guardada.",
            "Plus => Mais",
            "Ville estimee par internet (peut etre fausse) => Cidade estimada pela internet (pode estar errada)",
            "Source : position saisie => Fonte: posicao digitada",
            "Ce n'est pas ma ville ? Choisir ma ville => Nao e minha cidade? Escolher minha cidade",
            "Ma ville => Minha cidade",
            "Cherche ta ville, choisis-la dans la liste : elle est gardee, et plus jamais remplacee par une estimation. Aucune coordonnee n'est affichee. => Procure sua cidade e escolha na lista: ela e mantida e nunca substituida por uma estimativa. Nenhuma coordenada e exibida.",
            "Position automatique => Posicao automatica",
            "Utiliser la position de Windows (Wi-Fi / GPS) => Usar a localizacao do Windows (Wi-Fi / GPS)",
            "Estimer par internet => Estimar pela internet",
            "Un PC fixe n'a pas de GPS : Windows et internet ne donnent que la zone de ton fournisseur d'acces, parfois a des dizaines de km. La position est arrondie a 1 km environ et jamais affichee. => Um PC de mesa nao tem GPS: o Windows e a internet so dao a area do seu provedor, as vezes a dezenas de km. A posicao e arredondada para cerca de 1 km e nunca exibida.",
            "Coordonnees (avance) => Coordenadas (avancado)",
            "latitude, longitude => latitude, longitude",
            "Ma position => Minha posicao",
            "Scene 3D => Cena 3D",
            "Hauteur de l'ile => Altura da ilha",
            "Taille du cadre => Tamanho da moldura",
            "Comme avant => Como antes",
            "Un peu plus bas => Um pouco mais baixo",
            "Plus bas => Mais baixo",
            "Tres bas => Muito baixo",
            "Page Plus => Pagina Mais",
            "Page Plus (tester tous les temps) => Pagina Mais (testar todo o tempo)",
            "La page Plus permet de voir tous les types de temps a la main (heure, vent, temperature). Elle reste cachee tant que tu ne l'actives pas. => A pagina Mais permite ver todos os tipos de tempo manualmente (hora, vento, temperatura). Fica oculta ate voce ativa-la.",
            "Ouvrir la page Plus => Abrir a pagina Mais",
            "Alchimie => Alquimia",
            "Ambiance => Ambiente",
            "Cubes => Cubos",
            "Particules => Particulas",
            "Tunnel => Tunel",
            "Pics => Picos",
            "Feux d'artifice => Fogos de artificio",
            "Couleurs musicales => Cores musicais",
            "Toile => Teia",
            "Clic : agrandir / reduire => Clique: ampliar / reduzir",
            "DJ => DJ",
            "Boucle => Loop",
            "Charger... => Carregar...",
            "Ejecter => Ejetar",
            "Filtre => Filtro",
            "Crossfader => Crossfader",
            "Mix => Mix",
            "Coupe => Corte",
            "Chargement... => Carregando...",
            "Aucune piste : Charger... => Sem faixa: Carregar...",
            "BPM inconnu => BPM desconhecido",
            "Charger dans la platine A => Carregar no deck A",
            "Charger dans la platine B => Carregar no deck B",
            "La liste est vide. Ajoute des musiques (elles sont aussi dans l'onglet Musique). => A lista esta vazia. Adicione musicas (sao as mesmas da aba Musica).",
            "Retour aux platines => Voltar aos decks",
            "Une piste est lue en entier (10 minutes au maximum). L'analyse du tempo prend quelques secondes. => Uma faixa e lida por inteiro (maximo 10 minutos). A analise do tempo leva alguns segundos.",
            "Les pistes sortent par la tranche Musique (son general inclus). Le tempo change aussi la hauteur du son (comme un tourne-disque). Les reperes ne sont pas gardes. => As faixas saem pelo canal Musica (principal incluido). O tempo tambem muda o tom (como um toca-discos). Os pontos cue nao sao salvos.",
            "Tempo 0 => Tempo 0",
            "Piste precedente => Faixa anterior",
            "Piste suivante => Proxima faixa",
            "Lire / Pause => Reproduzir / Pausa",
            "Notifications => Notificacoes",
            "Alarmes, evenements, problemes et musique en cours => Alarmes, eventos, problemas e musica em reproducao",
            "Musique en cours => Tocando agora",
            "Rien a signaler. => Nada a informar.",
            "Effacer => Apagar",
            "Tout effacer => Apagar tudo",
            "Connexion perdue => Conexao perdida",
            "Plus de donnees du casque (ar6dof_probe lance ?) => Sem dados do headset (ar6dof_probe esta rodando?)",
            "Suivi perdu => Rastreamento perdido",
            "Le suivi de la tete ne fonctionne plus => O rastreamento da cabeca nao funciona mais",
            "Calendrier => Calendario",
            "Evenement => Evento",
            "Dans {0} min => Em {0} min",
            "Evenements avec rappel avant leur debut, et scan d'une affiche ou d'un programme de convention. => Eventos com lembrete antes do inicio e leitura de um cartaz ou da programacao de uma convencao.",
            "Evenements avec rappel avant leur debut. Scanne une affiche ou le programme d'une convention devant toi pour les creer. Le scan ne tourne que quand tu le lances. => Eventos com lembrete antes do inicio. Leia um cartaz ou a programacao de uma convencao na sua frente para cria-los. A leitura so roda quando voce inicia.",
            "Calendrier indisponible. => Calendario indisponivel.",
            "Agenda => Agenda",
            "Scanner => Escanear",
            "(sans rappel) => (sem lembrete)",
            "Ajouter un evenement => Adicionar um evento",
            "Aucun evenement. Va dans Scanner pour lire une affiche ou un programme, ou ajoute-en un a la main. => Nenhum evento. Va em Escanear para ler um cartaz ou programacao, ou adicione um a mao.",
            "Nouvel evenement => Novo evento",
            "Modifier l'evenement => Editar evento",
            "Nom de l'evenement => Nome do evento",
            "Lieu (facultatif) => Local (opcional)",
            "Duree inconnue => Duracao desconhecida",
            "Duree => Duracao",
            "Rappel avant le debut => Lembrete antes do inicio",
            "Le rappel sonne {0} min avant (a regler dans Options). => O lembrete toca {0} min antes (ajuste em Opcoes).",
            "Tiens l'affiche ou le programme bien en face de toi, texte lisible et bien eclaire, sans bouger. Touche Lancer : photo dans 3 secondes, lecture du texte par Windows, puis tu relis les evenements avant de les enregistrer. Rien ne tourne avant ton clic. => Segure o cartaz ou a programacao bem na sua frente, com o texto legivel e bem iluminado, sem se mexer. Toque em Iniciar: foto em 3 segundos, leitura do texto pelo Windows e depois voce revisa os eventos antes de salvar. Nada roda antes do seu clique.",
            "Lancer le scan => Iniciar leitura",
            "Scan dans {0} s... => Leitura em {0} s...",
            "Photo... => Foto...",
            "Lecture du texte... => Lendo o texto...",
            "Camera indisponible : le passthrough n'est pas pret => Camera indisponivel: o passthrough nao esta pronto",
            "Photo impossible : {0} => Foto impossivel: {0}",
            "Photo impossible : rien n'a ete enregistre => Foto impossivel: nada foi salvo",
            "Aucun horaire reconnu. Rapproche-toi, ameliore la lumiere, ou regarde le texte lu ci-dessous. => Nenhum horario reconhecido. Aproxime-se, melhore a luz ou veja o texto lido abaixo.",
            "{0} evenement(s) trouve(s). Decoche ceux que tu ne veux pas, touche une ligne pour corriger. => {0} evento(s) encontrado(s). Desmarque os que nao quer, toque em uma linha para corrigir.",
            "Enregistrer ({0}) => Salvar ({0})",
            "Nouveau scan => Nova leitura",
            "Cacher le texte lu => Ocultar o texto lido",
            "Voir le texte lu => Ver o texto lido",
            "Aucun texte lu. => Nenhum texto lido.",
            "Rien de nouveau a enregistrer => Nada novo para salvar",
            "{0} evenement(s) ajoute(s) => {0} evento(s) adicionado(s)",
            "Rappel => Lembrete",
            "Le rappel sonne avant le debut de l'evenement : => O lembrete toca antes do inicio do evento:",
            "Le rappel passe par la sonnerie de l'horloge et laisse une ligne dans les notifications. Il sonne meme si cette fenetre est fermee. => O lembrete usa o toque do relogio e deixa uma linha nas notificacoes. Toca mesmo com esta janela fechada.",
            "Scan => Leitura",
            "La photo du scan est lue par Windows sur ton PC (rien n'est envoye sur Internet), puis supprimee tout de suite. => A foto da leitura e lida pelo Windows no seu PC (nada e enviado pela Internet) e apagada logo em seguida.",
            "Donnees => Dados",
            "Confirmer : tout effacer ? => Confirmar: apagar tudo?",
            "Effacer tous les evenements => Excluir todos os eventos",
